def rnn_cell(num_units, dropout, mode, residual=False, name=None, reuse=None):
    dropout = dropout if mode == tf.estimator.ModeKeys.TRAIN else 0.0

    cell = tf.nn.rnn_cell.GRUCell(num_units, name=name, reuse=reuse)

